  function contextStep(){const t=norm(document.body.innerText||'');if(t.includes('isquemia mesenter'))return 'Con esta sospecha, el estudio dirigido que más pesa es una angio-TC: quiero demostrar el compromiso vascular y la viabilidad intestinal.';if(t.includes('pancreat'))return 'Si la sospecha es pancreatitis, priorizo lipasa, función renal, hepatograma y gravedad; la imagen la uso cuando cambia conducta o hay complicaciones.';if(t.includes('periton'))return 'Si hay peritonitis, busco repercusión sistémica con laboratorio y lactato, y una TC con contraste si el paciente está estable para localizar la causa.';if(t.includes('crohn')||t.includes('colitis')||t.includes('ulcerosa'))return 'En enfermedad inflamatoria intestinal, separo actividad, infección y complicaciones: hemograma/PCR, materia fecal y luego endoscopia o imagen según estabilidad.';return 'Después elijo el estudio dirigido según la hipótesis clínica; no pido una prueba porque sí, sino porque puede confirmar etiología o cambiar conducta.'}
  function guidedTakeover(el){const steps=['Tomo el caso. Primero verifico estabilidad, monitorización y acceso venoso. Antes de diagnosticar, aseguro que el paciente esté seguro.','Ahora reviso estudios básicos: hemograma, función renal, electrolitos y, si corresponde por gravedad, lactato/gasometría. Busco repercusión y contraindicaciones para el siguiente paso.',contextStep(),'Con los hallazgos integrados, inicio el tratamiento específico y explico qué objetivo fisiológico o etiológico persigue cada medida.','Por último reevalúo respuesta y recién entonces defino destino: observación, internación, cirugía/UCI o alta segura según el caso.'];let i=0;const advance=()=>{if(i<steps.length){showVega(steps[i],[]);i++;setTimeout(advance,1150);return}showVega('Listo. Voy a ejecutar ahora la resolución del caso con esos criterios y dejar el resultado registrado.',[]);setTimeout(()=>{hideVega();triggerOriginalVega(el)},850)};advance()}
