  const obs=new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes){if(n.nodeType!==1)continue;const tw=document.createTreeWalker(n,NodeFilter.SHOW_TEXT);let x;while((x=tw.nextNode())){if(x.nodeValue&&x.nodeValue.includes('Completo el tratamiento y el destino seguro.'))x.nodeValue=x.nodeValue.replace('Completo el tratamiento y el destino seguro.','Completo el tratamiento y el destino seguro. Si querés, después repasamos por qué cada paso fue adecuado.')}}});
